"""PSLE-style items for sci-interactions-env-survival, all tiers (round sci-fill-env-survival-2026-11-20)."""
from fillkit import add, table, graph, lint
from figs_eco import meadow, pond, forest

SUB, FILE = "sci-interactions-env-survival", "sci-env-survival.json"
FC, FT, RD = "sci-pat-food-chain-web", "sci-pat-fair-test-design", "sci-pat-read-data"
B, I, C = "basic", "intermediate", "competent"
P = []
def q(*a): P.append(a)
def W(t, tag, why): return (t, tag, why)
def tb(h, r, w, c): return lambda: table(h, r, w, c)
MEAD, POND, FOR = meadow, pond, forest

# ---------------- basic ----------------
q("es-001", B, 3, FC, "Look at the food chain: grass, grasshopper, frog, snake. Which organism is the producer?", "Grass", [W("Grasshopper", "consumer", "A grasshopper cannot make its own food. It eats grass, so it is a consumer."), W("Frog", "consumer", "A frog eats other animals, so it is a consumer."), W("Snake", "consumer", "A snake eats other animals, so it is a consumer.")], ["A producer makes its own food. Only the green plant, grass, does that."], None)
q("es-002", B, 3, FC, "What does the arrow in a food chain show?", "Energy passing from the food to the animal that eats it", [W("Energy passing from the animal to the food it eats", "reversed", "The arrow points to the eater, not to the food."), W("The direction in which the animal walks", "wrong-idea", "The arrows show feeding, not movement."), W("The bigger animal pointing at the smaller one", "wrong-idea", "The size of the animals does not decide the direction.")], ["The arrow points from the food to the organism that eats it, in the direction energy flows."], None)
