q("es-005", B, 3, FC, "In the food chain algae, water flea, small fish, big fish, which organism is the predator of the small fish?", "Big fish", [W("Algae", "wrong-role", "Algae are producers. They do not eat fish."), W("Water flea", "wrong-role", "The water flea is eaten by the small fish."), W("Small fish", "wrong-role", "The small fish is the prey, not its own predator.")], ["The big fish eats the small fish, so it is the predator."], None)
q("es-006", B, 3, FC, "Where does the energy at the start of most food chains come from?", "The Sun", [W("The soil", "wrong-source", "Soil gives plants minerals, but not the energy they need to make food."), W("The water", "wrong-source", "Plants need water, but it is not their source of energy."), W("The air", "wrong-source", "Plants use gases from the air, but the energy comes from the Sun.")], ["Plants take in light energy from the Sun to make food, and animals get this energy when they eat."], None)
q("es-007", B, 1, FC, "Which of the following is a non-living thing that affects how fish survive in a pond?", "The temperature of the water", [W("The plants in the pond", "living", "Plants are living things."), W("The other fish in the pond", "living", "Other fish are living things."), W("The insects on the water", "living", "Insects are living things.")], ["Temperature is not a living thing, but it affects how fish survive."], None)
q("es-008", B, 1, FC, "Which of the following is a living factor that can affect the survival of a rabbit?", "A fox that hunts rabbits", [W("The amount of rain", "non-living", "Rain is not a living thing."), W("The temperature of the air", "non-living", "Temperature is not a living thing."), W("The amount of sunlight", "non-living", "Sunlight is not a living thing.")], ["Predators such as foxes are living things that affect the rabbits."], None)
q("es-009", B, 2, FC, "A pond dries up in a very long dry spell. What will most likely happen to the fish that live in it?", "They die because they cannot live out of water", [W("They fly away to another pond nearby", "wrong-idea", "Fish do not have wings and cannot leave the water."), W("They grow legs and walk to another pond", "wrong-idea", "Fish cannot change their bodies in a short time."), W("They live on the dry land around the pond", "wrong-idea", "Fish need water to breathe, so they cannot live on dry land.")], ["Fish cannot move out of a pond that has dried up and cannot breathe on land, so they die."], None)
q("es-010", B, 2, FC, "Which of the following moves to another place when the weather becomes unfavourable?", "A bird that flies to a warmer country in winter", [W("A tree that sheds all its leaves in the dry season", "wrong-idea", "A tree cannot move. It stays where it is."), W("A snail that stays inside its shell until it rains", "wrong-idea", "The snail stays in the same place."), W("A mushroom that grows again on a rotting log", "wrong-idea", "A mushroom cannot move.")], ["Birds can fly, so they move to places where the weather and food are better."], None)
